19	// Result codes.  They mirror the granularity that 7-Zip's messages need.
20	enum ErrKind {
21	  ERR_OK = 0,
22	  ERR_DATA,             // "Data error"
23	  ERR_CRC,              // "CRC failed"
24	  ERR_UNEXPECTED_END,   // "Unexpected end of data"
25	  ERR_UNSUPPORTED,      // "Unsupported method"
26	  ERR_HEADERS,          // "Headers Error"
27	  ERR_PASSWORD,         // wrong password
28	  ERR_NOT_ARCHIVE,      // "Is not archive"
29	  ERR_NOTIMPL,          // E_NOTIMPL
30	  ERR_MEMORY,           // E_OUTOFMEMORY
31	  ERR_FAIL,             // E_FAIL
32	  ERR_SYSTEM,           // errno based
33	  ERR_USER,             // command line error
34	  ERR_ABORT             // user break
35	};
36	
37	struct Exc {
38	  ErrKind kind;
39	  std::string msg;      // optional extra text
40	  int sysErrno;
41	  Exc(ErrKind k) : kind(k), sysErrno(0) {}
42	  Exc(ErrKind k, const std::string &m) : kind(k), msg(m), sysErrno(0) {}
43	};
