45	inline void ThrowData()       { throw Exc(ERR_DATA); }
46	inline void ThrowCrc()        { throw Exc(ERR_CRC); }
47	inline void ThrowEnd()        { throw Exc(ERR_UNEXPECTED_END); }
48	inline void ThrowUnsup()      { throw Exc(ERR_UNSUPPORTED); }
49	inline void ThrowHeaders()    { throw Exc(ERR_HEADERS); }
50	inline void ThrowMem()        { throw Exc(ERR_MEMORY); }
51	inline void ThrowNotImpl()    { throw Exc(ERR_NOTIMPL); }
52	inline void ThrowFail()       { throw Exc(ERR_FAIL); }
53	inline void ThrowUser(const std::string &m) { throw Exc(ERR_USER, m); }
