55	// ---------------------------------------------------------------- byte access
56	
57	inline UInt16 GetUi16(const Byte *p) { UInt16 v; memcpy(&v, p, 2); return v; }
58	inline UInt32 GetUi32(const Byte *p) { UInt32 v; memcpy(&v, p, 4); return v; }
59	inline UInt64 GetUi64(const Byte *p) { UInt64 v; memcpy(&v, p, 8); return v; }
60	inline void SetUi16(Byte *p, UInt16 v) { memcpy(p, &v, 2); }
61	inline void SetUi32(Byte *p, UInt32 v) { memcpy(p, &v, 4); }
62	inline void SetUi64(Byte *p, UInt64 v) { memcpy(p, &v, 8); }
63	
64	inline UInt16 GetBe16(const Byte *p) { return (UInt16)(((UInt32)p[0] << 8) | p[1]); }
65	inline UInt32 GetBe32(const Byte *p) {
66	  return ((UInt32)p[0] << 24) | ((UInt32)p[1] << 16) | ((UInt32)p[2] << 8) | p[3];
67	}
68	inline UInt64 GetBe64(const Byte *p) { return ((UInt64)GetBe32(p) << 32) | GetBe32(p + 4); }
69	inline void SetBe32(Byte *p, UInt32 v) {
70	  p[0] = (Byte)(v >> 24); p[1] = (Byte)(v >> 16); p[2] = (Byte)(v >> 8); p[3] = (Byte)v;
71	}
72	inline void SetBe64(Byte *p, UInt64 v) { SetBe32(p, (UInt32)(v >> 32)); SetBe32(p + 4, (UInt32)v); }
