78	// A growable output buffer with a cheap append.
79	struct DynBuf {
80	  ByteBuf v;
81	  void add(const void *p, size_t n) {
82	    const Byte *s = (const Byte *)p;
83	    v.insert(v.end(), s, s + n);
84	  }
85	  void addByte(Byte b) { v.push_back(b); }
86	  size_t size() const { return v.size(); }
87	  Byte *data() { return v.empty() ? nullptr : &v[0]; }
88	  const Byte *data() const { return v.empty() ? nullptr : &v[0]; }
89	};
